// ---------------------------------------------------------------- day & night
// timeOfDay t runs 0..1: 0 = midnight, 0.25 = sunrise, 0.5 = noon, 0.75 = sunset.
export const DAY_NIGHT = {
  cycleSeconds: 600,      // one full day+night = 10 minutes
  startTime: 0.3,         // new games start in the morning
  nightStart: 0.79,       // night creatures begin hunting after this...
  nightEnd: 0.21,         // ...until this (wraps through midnight)
  canSleepAfter: 0.7,     // beds work from evening onwards
  wakeTime: 0.26,         // sleeping skips to this time
};
export function isNight(t) { return t >= DAY_NIGHT.nightStart || t < DAY_NIGHT.nightEnd; }

