// Each hero has their OWN power (index into POWERS). Always usable by that hero, in every mode.
const HERO_POWER = { aria: 0 /* Life */, bram: 4 /* Earth */, kira: 5 /* Lightning */, leo: 6 /* Light */, luna: 3 /* Ice */,
  rex: 2 /* Fire */, nova: 7 /* Darkness - black holes from space */, ivy: 1 /* Healing */, zane: 8 /* Death */ };
for (const c of CHARACTERS) c.power = HERO_POWER[c.id];

