// ---------------------------------------------------------------- levels
export function xpForLevel(level) { return Math.round(60 * Math.pow(level, 1.6)); }
export const LEVEL_UP = { hp: 10, mana: 5, strength: 0.03 };

// enemy stats in data are for level 1; game code scales them with the dimension's level:
export function enemyScale(level) { return { hp: 1 + 0.8 * (level - 1), dmg: 1 + 0.45 * (level - 1), coins: 1 + 0.6 * (level - 1) }; }

