const TEMPLE_NAMES = ['Shrine', 'Temple', 'Great Temple'];
const TEMPLE_HP = [0.45, 0.7, 1.15];   // x the dimension boss's hp - each temple is stronger than the last
const TEMPLE_DMG = [0.75, 0.9, 1.1];
DIMENSIONS.forEach((d, i) => {
  d.temples = TEMPLE_GUARDIANS[i].map((g, t) => ({
    tier: t,
    name: `${TEMPLE_NAMES[t]} of ${POWERS[i].name}`,
    moves: [3 * t, 3 * t + 1, 3 * t + 2],
    boss: { ...g, hp: Math.round(d.boss.hp * TEMPLE_HP[t]), dmg: Math.round(d.boss.dmg * TEMPLE_DMG[t]) },
  }));
  d.keyFor = i < 8 ? i + 1 : null;   // the key this dimension's boss drops opens portal i+1
});

